package ch.bbw.zork;/** * Group: Cat team, * Version: 1.0, * Date: October 2026 */import java.util.ArrayList;import java.util.Collections;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;/** * A room of the house. A room has a description, exits to other rooms * (north, east, south, west, up, down), any number of {@link Item}s and * can be the winning room of the game. */public class Room {	private final String description;	private final Map<String, Room> exits;	private final List<Item> items;	private boolean winningRoom;	/**	 * Creates a room without exits and without items.	 *	 * @param description a short description, e.g. "the kitchen"	 */	public Room(String description) {		this.description = description;		this.exits = new LinkedHashMap<>();		this.items = new ArrayList<>();		this.winningRoom = false;	}	/**	 * Sets the four horizontal exits at once. A null value means: no exit.	 *	 * @param north the room in the north or null	 * @param east  the room in the east or null	 * @param south the room in the south or null	 * @param west  the room in the west or null	 */	public void setExits(Room north, Room east, Room south, Room west) {		setExit("north", north);		setExit("east", east);		setExit("south", south);		setExit("west", west);	}	/**	 * Sets one exit, for example "up" or "down".	 *	 * @param direction the direction name	 * @param room      the room behind the exit, null removes the exit	 */	public void setExit(String direction, Room room) {		if (room == null) {			exits.remove(direction);		} else {			exits.put(direction, room);		}	}	/** @return the short description of the room */	public String shortDescription() {		return description;	}	/**	 * @return the description with exits and items, as shown when the player enters	 */	public String longDescription() {		StringBuilder stringBuilder = new StringBuilder("You are in " + description + ".\n");		stringBuilder.append(itemString()).append("\n");		stringBuilder.append(exitString());		return stringBuilder.toString();	}	private String exitString() {		return "Exits: " + String.join(" ", exits.keySet());	}	/** @return a text which lists all items in this room */	public String itemString() {		if (items.isEmpty()) {			return "There is nothing here.";		}		StringBuilder stringBuilder = new StringBuilder("You see:");		for (Item item : items) {			stringBuilder.append(" ").append(item.toString()).append(";");		}		return stringBuilder.toString();	}	/**	 * @param direction the direction the player wants to go	 * @return the room in this direction or null if there is no exit	 */	public Room nextRoom(String direction) {		return exits.get(direction);	}	/**	 * Puts an item into this room.	 *	 * @param item the item to add	 */	public void addItem(Item item) {		items.add(item);	}	/**	 * Removes an item from this room.	 *	 * @param item the item to remove	 * @return true if the item was in the room	 */	public boolean removeItem(Item item) {		return items.remove(item);	}	/**	 * Searches an item by its name (ignoring upper and lower case).	 *	 * @param name the name of the item	 * @return the item or null if there is no such item in this room	 */	public Item findItem(String name) {		for (Item item : items) {			if (item.hasName(name)) {				return item;			}		}		return null;	}	/** @return a read-only view of all items in this room */	public List<Item> getItems() {		return Collections.unmodifiableList(items);	}	/** @return true if the player reaches the goal of the game in this room */	public boolean isWinningRoom() {		return winningRoom;	}	/**	 * Marks this room as the winning room (or not).	 *	 * @param winningRoom true if this is the winning room	 */	public void setWinningRoom(boolean winningRoom) {		this.winningRoom = winningRoom;	}}